CREATE TABLE app_users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, display_name VARCHAR(120) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('ADMIN','WAREHOUSE','VIEWER')), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE suppliers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, phone VARCHAR(40), address VARCHAR(400));
CREATE TABLE parts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, unit VARCHAR(40) NOT NULL, minimum DECIMAL(18,3) NOT NULL DEFAULT 0 CHECK(minimum>=0));
CREATE TABLE locations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL);
INSERT INTO locations(code,name) VALUES('MAIN','Kho Vĩnh Khang');
CREATE TABLE stock_balances(part_id BIGINT REFERENCES parts(id), location_id BIGINT REFERENCES locations(id), quantity DECIMAL(18,3) NOT NULL DEFAULT 0 CHECK(quantity>=0), PRIMARY KEY(part_id,location_id));
CREATE TABLE stock_documents(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, type VARCHAR(10) NOT NULL CHECK(type IN ('IN','OUT')), supplier_id BIGINT REFERENCES suppliers(id), location_id BIGINT NOT NULL REFERENCES locations(id), status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','POSTED')), note VARCHAR(500), created_by BIGINT NOT NULL REFERENCES app_users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, posted_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE stock_document_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, document_id BIGINT NOT NULL REFERENCES stock_documents(id), part_id BIGINT NOT NULL REFERENCES parts(id), quantity DECIMAL(18,3) NOT NULL CHECK(quantity>0), unit_cost DECIMAL(18,2) NOT NULL DEFAULT 0 CHECK(unit_cost>=0), UNIQUE(document_id,part_id));
CREATE TABLE vehicle_models(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL);
CREATE TABLE bom_versions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, model_id BIGINT NOT NULL REFERENCES vehicle_models(id), version INTEGER NOT NULL CHECK(version>0), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','RETIRED')), UNIQUE(model_id,version));
CREATE TABLE bom_lines(bom_id BIGINT REFERENCES bom_versions(id), part_id BIGINT REFERENCES parts(id), quantity DECIMAL(18,3) NOT NULL CHECK(quantity>0), PRIMARY KEY(bom_id,part_id));
CREATE TABLE production_orders(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, bom_id BIGINT NOT NULL REFERENCES bom_versions(id), quantity INTEGER NOT NULL CHECK(quantity>0), color VARCHAR(60) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','COMPLETED')), created_by BIGINT NOT NULL REFERENCES app_users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE production_materials(order_id BIGINT REFERENCES production_orders(id), part_id BIGINT REFERENCES parts(id), quantity DECIMAL(18,3) NOT NULL CHECK(quantity>0), PRIMARY KEY(order_id,part_id));
CREATE TABLE vehicles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, model_id BIGINT NOT NULL REFERENCES vehicle_models(id), order_id BIGINT NOT NULL REFERENCES production_orders(id), color VARCHAR(60) NOT NULL, frame_number VARCHAR(100) NOT NULL UNIQUE, motor_number VARCHAR(100) NOT NULL UNIQUE, status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN ('AVAILABLE','SHIPPED')), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vehicle_shipments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, customer VARCHAR(200) NOT NULL, created_by BIGINT NOT NULL REFERENCES app_users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vehicle_shipment_lines(shipment_id BIGINT REFERENCES vehicle_shipments(id), vehicle_id BIGINT NOT NULL UNIQUE REFERENCES vehicles(id), PRIMARY KEY(shipment_id,vehicle_id));
CREATE TABLE stock_movements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, part_id BIGINT NOT NULL REFERENCES parts(id), location_id BIGINT NOT NULL REFERENCES locations(id), quantity DECIMAL(18,3) NOT NULL CHECK(quantity<>0), document_id BIGINT REFERENCES stock_documents(id), production_id BIGINT REFERENCES production_orders(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK((document_id IS NOT NULL AND production_id IS NULL) OR (document_id IS NULL AND production_id IS NOT NULL)));
CREATE TABLE audit_log(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_users(id), action VARCHAR(80) NOT NULL, entity VARCHAR(80) NOT NULL, entity_id BIGINT, details VARCHAR(1000), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_movements_part ON stock_movements(part_id,created_at);
CREATE INDEX idx_audit_date ON audit_log(created_at);
